export type AppLevel = 'ecosystem' | 'workplace' | 'project' | 'admin'

export type AppDefinition = {
  id: string
  label: string
  description: string
  level: AppLevel
  route: string
  icon: string
  premium?: boolean
  featureFlag?: string
  dependencies?: string[]
  audience?: string
  pricing?: 'free' | 'paid' | 'credit'
}

export type AppInstallation = {
  id: string
  appId: string
  tenantId: string
  projectId?: string
  enabledBy: string
  enabledAt: string
  status: 'active' | 'disabled'
}
